import { useState } from "react";
import { useApp } from "../../context/AppContext";
import { Sheet, BelgeRow, EmptyState } from "../../components/UI";

const IlanKart = ({ ilan, onClick }) => (
  <div className="card" style={{ marginBottom: 10, borderLeft: "3px solid var(--sari)", cursor: "pointer", borderRadius: "var(--r-lg)" }} onClick={onClick}
    onMouseEnter={e => e.currentTarget.style.borderLeftColor = "var(--turuncu)"}
    onMouseLeave={e => e.currentTarget.style.borderLeftColor = "var(--sari)"}
  >
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
      <div className="display" style={{ fontSize: 18 }}>{ilan.yuk}</div>
      <div className="price">₺{ilan.ucret.toLocaleString()}</div>
    </div>
    <div className="rota" style={{ marginBottom: 10 }}>
      <span className="rota-city">{ilan.nereden}</span>
      <span className="rota-arrow">—→</span>
      <span className="rota-city">{ilan.nereye}</span>
    </div>
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
      <span className="chip chip-accent">⚖️ {ilan.ton}t</span>
      <span className="chip chip-blue">⏱ {ilan.sure}</span>
      <span className="chip">📅 {ilan.tarih}</span>
      <span className="chip">🚛 {ilan.aracTip}</span>
    </div>
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingTop: 10, borderTop: "1px solid var(--border)" }}>
      <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text2)" }}>🏢 {ilan.issizAd}</span>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        <span className="rating">⭐ {ilan.issizPuan}</span>
        <span className="chip" style={{ fontSize: 10 }}>{ilan.teklifSayisi} teklif</span>
      </div>
    </div>
  </div>
);

const IlanDetay = ({ ilan, onKapat }) => {
  const { teklifEkle, oturum } = useApp();
  const [teklifMiktar, setTeklifMiktar] = useState(ilan.ucret);
  const [gonderildi, setGonderildi] = useState(false);

  const gonder = () => {
    teklifEkle({ ilanId: ilan.id, kamyoncuAd: oturum.ad, plaka: "34 TYK 421", teklif: Number(teklifMiktar), durum: "bekliyor", puan: 4.9 });
    setGonderildi(true);
    setTimeout(onKapat, 1500);
  };

  return (
    <Sheet onClose={onKapat}>
      <div className="display" style={{ fontSize: 24, color: "var(--sari)", marginBottom: 4 }}>{ilan.yuk}</div>
      <div className="rota" style={{ marginBottom: 6 }}>
        <span className="rota-city">{ilan.nereden}</span>
        <span className="rota-arrow">—→</span>
        <span className="rota-city">{ilan.nereye}</span>
      </div>
      <div style={{ color: "var(--text2)", fontSize: 13, lineHeight: 1.7, marginBottom: 16 }}>{ilan.aciklama}</div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 16 }}>
        {[
          { k: "Tonaj", v: `${ilan.ton} Ton` },
          { k: "Ücret", v: `₺${ilan.ucret.toLocaleString()}` },
          { k: "Süre", v: ilan.sure },
          { k: "Araç Tipi", v: ilan.aracTip },
          { k: "Tarih", v: ilan.tarih },
          { k: "İş Veren Puanı", v: `⭐ ${ilan.issizPuan}` },
        ].map(({ k, v }) => (
          <div key={k} style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "10px 12px" }}>
            <div className="label" style={{ marginBottom: 3 }}>{k}</div>
            <div style={{ fontSize: 13, fontWeight: 600 }}>{v}</div>
          </div>
        ))}
      </div>

      <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: 14, marginBottom: 16 }}>
        <div className="label" style={{ marginBottom: 10 }}>📁 İş Veren Belgeleri</div>
        {ilan.belgeler.map((b, i) => <BelgeRow key={i} belge={b} />)}
      </div>

      {!gonderildi ? (
        <>
          <div className="input-group">
            <label className="label">Teklif tutarınız (₺)</label>
            <input className="input" type="number" value={teklifMiktar} onChange={e => setTeklifMiktar(e.target.value)} />
          </div>
          <button className="btn btn-primary btn-display btn-full" onClick={gonder}>🚛 TEKLİF VER</button>
        </>
      ) : (
        <div style={{ textAlign: "center", padding: 20, color: "var(--yesil)" }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>✅</div>
          <div style={{ fontFamily: "var(--font-d)", fontSize: 20 }}>TEKLİF GÖNDERİLDİ!</div>
        </div>
      )}
    </Sheet>
  );
};

export default function IlanlarSayfasi() {
  const { ilanlar } = useApp();
  const [filtre, setFiltre] = useState("");
  const [secilan, setSecilan] = useState(null);

  const liste = ilanlar.filter(i =>
    i.nereden.toLowerCase().includes(filtre.toLowerCase()) ||
    i.nereye.toLowerCase().includes(filtre.toLowerCase()) ||
    i.yuk.toLowerCase().includes(filtre.toLowerCase())
  );

  return (
    <div className="scroll-content">
      <div className="search-bar">
        <span className="search-icon">🔍</span>
        <input placeholder="Şehir veya yük türü ara..." value={filtre} onChange={e => setFiltre(e.target.value)} />
        {filtre && <button onClick={() => setFiltre("")} style={{ color: "var(--text3)", fontSize: 14 }}>✕</button>}
      </div>

      <div className="section-title">AKTİF İLANLAR ({liste.length})</div>

      {liste.length === 0
        ? <EmptyState icon="🔍" text="Sonuç bulunamadı" />
        : liste.map(i => <IlanKart key={i.id} ilan={i} onClick={() => setSecilan(i)} />)
      }

      {secilan && <IlanDetay ilan={secilan} onKapat={() => setSecilan(null)} />}
    </div>
  );
}
